actions.script:
// requestItemList and bulkRequestItemList intentionally not used —
// the gateway re-queries the DB for all fieldbus configuration.

// resolve gateway base URL and optional API key
const rawUri = request.brokerUri;
if (!rawUri) {
    ec.message.addError(`DeviceRequest ${request.requestName} (deviceId=${request.deviceId}) is missing brokerUri. Set brokerUri to the gateway REST base URL (e.g. http://gateway-host:8081 or http://gateway-host:8081?apiKey=secret).`);
    return;
}

let gatewayBaseUrl = rawUri;
let apiKey = null;
const qIdx = rawUri.indexOf('?');
if (qIdx >= 0) {
    gatewayBaseUrl = rawUri.substring(0, qIdx);
    const queryParams = rawUri.substring(qIdx + 1).split('&');
    for (const kv of queryParams) {
        const parts = kv.split('=', 2);
        if (parts.length === 2 && 'apiKey' === parts[0].trim()) apiKey = parts[1].trim();
    }
}
gatewayBaseUrl = gatewayBaseUrl.replace(/\/+$/, '');

// resolve gateway-side requestName from DeviceRequest.query
const gwRequestName = request.query;
if (!gwRequestName) {
    ec.message.addError(`DeviceRequest ${request.requestName} (deviceId=${request.deviceId}) is missing query. Set query to the gateway-side requestName (the DeviceRequest the gateway will look up in the shared DB).`);
    return;
}

const reqType = request.requestTypeEnumId;
const path = `/api/device-request/run/${gwRequestName}`;

// protocol detection (for logging only)
const isOpcUa = ('DcdOpcUa' === connection?.driverEnumId);
ec.logger.info(`Dispatching ${reqType} to gateway ${gatewayBaseUrl}${path} [protocol=${isOpcUa ? 'OPC UA' : 'MQTT'}, gwRequest=${gwRequestName}]`);

// call gateway
let targetUrl = `${gatewayBaseUrl}${path}`;
if (apiKey) targetUrl += `?apiKey=${encodeURIComponent(apiKey)}`;
ec.service.sync().name("moqui.device.DeviceGatewayServices.call#GatewayEndpoint")
    .parameters({ url: targetUrl }).call();

ec.logger.info(`Gateway dispatch completed for ${gwRequestName}`);

const dr = ec.entity.find("moqui.device.DeviceRequest")
    .condition("requestName", requestName).one();
if (!dr) {
    ec.message.addError(`DeviceRequest ${requestName} not found.`);
    return;
}

const rawUri = dr.brokerUri;
if (!rawUri) {
    ec.message.addError(`DeviceRequest ${requestName} is missing brokerUri (gateway REST base URL).`);
    return;
}
let gatewayBaseUrl = rawUri;
let apiKey = null;
const qIdx = rawUri.indexOf('?');
if (qIdx >= 0) {
    gatewayBaseUrl = rawUri.substring(0, qIdx);
    const queryParams = rawUri.substring(qIdx + 1).split('&');
    for (const kv of queryParams) {
        const parts = kv.split('=', 2);
        if (parts.length === 2 && 'apiKey' === parts[0].trim()) apiKey = parts[1].trim();
    }
}
gatewayBaseUrl = gatewayBaseUrl.replace(/\/+$/, '');

const payload = { deviceRuleSetId: deviceRuleSetId };
if (deviceId) payload.deviceId = deviceId;
if (deviceRuleId) payload.deviceRuleId = deviceRuleId;

let targetUrl = `${gatewayBaseUrl}/api/device-config/export`;
if (apiKey) targetUrl += `?apiKey=${encodeURIComponent(apiKey)}`;

let responseMap = {};
try {
    responseMap = ec.service.sync().name("moqui.device.DeviceGatewayServices.call#GatewayEndpoint")
        .parameters(Object.assign({ url: targetUrl }, payload)).call();
} catch (e) {
    ec.logger.error(`Error exporting device config: ${e}`);
}

const files = responseMap?.files;
let totalRows = 0;
if (Array.isArray(files)) {
    for (const f of files) {
        totalRows += (f.rowCount || 0);
    }
}

ec.service.sync().name("moqui.device.DeviceServices.receive#GatewayRequestCallback")
    .parameters({
        eventType: "exportCompleted",
        requestName: requestName,
        status: "completed",
        protocol: "Gateway Export",
        routeId: "run-device-config-export",
        rowCount: totalRows,
        message: `Device configuration export completed for rule set ${deviceRuleSetId}.`
    })
    .disableAuthz().call();

ec.logger.info(`DeviceConfig export completed for ruleSet ${deviceRuleSetId}`);

// load DeviceContent
const content = ec.entity.find("moqui.device.DeviceContent")
    .condition("deviceContentId", deviceContentId).one();
if (!content) {
    ec.message.addError(`DeviceContent ${deviceContentId} not found.`);
    return;
}
if (!content.contentLocation) {
    ec.message.addError(`DeviceContent ${deviceContentId} has no contentLocation.`);
    return;
}

// load Moqui-side DeviceRequest
const dr = ec.entity.find("moqui.device.DeviceRequest")
    .condition("requestName", requestName).one();
if (!dr) {
    ec.message.addError(`DeviceRequest ${requestName} not found.`);
    return;
}

// parse gateway base URL and optional API key from brokerUri
const rawUri = dr.brokerUri;
if (!rawUri) {
    ec.message.addError(`DeviceRequest ${requestName} is missing brokerUri (gateway REST base URL).`);
    return;
}
let gatewayBaseUrl = rawUri;
let apiKey = null;
const qIdx = rawUri.indexOf('?');
if (qIdx >= 0) {
    gatewayBaseUrl = rawUri.substring(0, qIdx);
    const queryParams = rawUri.substring(qIdx + 1).split('&');
    for (const kv of queryParams) {
        const parts = kv.split('=', 2);
        if (parts.length === 2 && 'apiKey' === parts[0].trim()) apiKey = parts[1].trim();
    }
}
gatewayBaseUrl = gatewayBaseUrl.replace(/\/+$/, '');

const gwRequestName = dr.query;
if (!gwRequestName) {
    ec.message.addError(`DeviceRequest ${requestName} is missing query (gateway-side requestName).`);
    return;
}

// read file bytes via Moqui resource system
const rr = ec.resource.getLocationReference(content.contentLocation);
const stream = rr.openStream();
let fileBytes;
try {
    fileBytes = stream.readAllBytes ? stream.readAllBytes() : stream.bytes;
} finally {
    if (stream && stream.close) stream.close();
}

let encoded = "";
if (typeof ec.resource.encodeBase64 === 'function') {
    encoded = ec.resource.encodeBase64(fileBytes);
} else if (typeof btoa === 'function') {
    encoded = btoa(fileBytes);
} else if (typeof globalThis.StringUtilities !== 'undefined' && globalThis.StringUtilities.base64UrlEncode) {
    encoded = globalThis.StringUtilities.base64UrlEncode(fileBytes);
}

const pathTokens = content.contentLocation.split('/');
const filename = pathTokens[pathTokens.length - 1];

ec.logger.info(`Transferring DeviceContent ${deviceContentId} (${filename}) to gateway ${gatewayBaseUrl} -> gwRequest=${gwRequestName}`);

let targetUrl = `${gatewayBaseUrl}/api/device-content/transfer/${gwRequestName}`;
if (apiKey) targetUrl += `?apiKey=${encodeURIComponent(apiKey)}`;

ec.service.sync().name("moqui.device.DeviceGatewayServices.call#GatewayEndpoint")
    .parameters({
        url: targetUrl,
        filename: filename,
        contentBase64: encoded,
        contentTypeEnumId: (content.contentTypeEnumId || '')
    }).call();

ec.logger.info(`DeviceContent transfer completed for ${gwRequestName}`);

const dr = ec.entity.find("moqui.device.DeviceRequest")
    .condition("requestName", requestName).one();
if (!dr) {
    ec.message.addError(`DeviceRequest ${requestName} not found.`);
    return;
}

const rawUri = dr.brokerUri;
if (!rawUri) {
    ec.message.addError(`DeviceRequest ${requestName} is missing brokerUri (gateway REST base URL).`);
    return;
}
let gatewayBaseUrl = rawUri;
let apiKey = null;
const qIdx = rawUri.indexOf('?');
if (qIdx >= 0) {
    gatewayBaseUrl = rawUri.substring(0, qIdx);
    const queryParams = rawUri.substring(qIdx + 1).split('&');
    for (const kv of queryParams) {
        const parts = kv.split('=', 2);
        if (parts.length === 2 && 'apiKey' === parts[0].trim()) apiKey = parts[1].trim();
    }
}
gatewayBaseUrl = gatewayBaseUrl.replace(/\/+$/, '');

const mqttTopic = dr.query || '';

// load waypoints in sequenceNum order
const samples = ec.entity.find("moqui.math.ApproximatedFunctionSample")
    .condition("approximatedFunctionId", approximatedFunctionId)
    .orderBy("sequenceNum").list();
if (!samples || samples.length === 0) {
    ec.message.addError(`No ApproximatedFunctionSample found for approximatedFunctionId ${approximatedFunctionId}.`);
    return;
}

const approxFunc = ec.entity.find("moqui.math.ApproximatedFunction")
    .condition("approximatedFunctionId", approximatedFunctionId).one();
const vectorSpaceEnumId = approxFunc?.vectorSpaceEnumId || '';
const axisNames = (vectorSpaceEnumId === 'EngTcpPose6Dof') ?
    ['X', 'Y', 'Z', 'A', 'B', 'C'] :
    ['J1', 'J2', 'J3', 'J4', 'J5', 'J6'];

// build per-axis arrays according to the trajectory vector space
const axes = {};
for (const sample of samples) {
    const components = ec.entity.find("moqui.math.VectorComponent")
        .condition("vectorId", sample.sampleVectorId)
        .orderBy("dimensionIndex").list();
    for (const comp of (components || [])) {
        const dim = parseInt(comp.dimensionIndex, 10);
        const axisKey = (dim < axisNames.length) ? axisNames[dim] : `D${dim}`;
        if (!axes[axisKey]) axes[axisKey] = [];
        axes[axisKey].push(Number(comp.realValue));
    }
}

const payload = {
    approximatedFunctionId: approximatedFunctionId,
    waypointCount: samples.length,
    mqttTopic: mqttTopic,
    axes: axes
};

ec.logger.info(`Exporting trajectory ${approximatedFunctionId} (${samples.length} waypoints, ${Object.keys(axes).length} axes) to gateway ${gatewayBaseUrl}, topic=${mqttTopic}`);

let targetUrl = `${gatewayBaseUrl}/api/trajectory/export`;
if (apiKey) targetUrl += `?apiKey=${encodeURIComponent(apiKey)}`;

ec.service.sync().name("moqui.device.DeviceGatewayServices.call#GatewayEndpoint")
    .parameters(Object.assign({ url: targetUrl }, payload)).call();

ec.logger.info(`Trajectory export completed for ${approximatedFunctionId}`);

if (eventType === 'inboundError') {
    ec.logger.warn(`Gateway inbound error on route ${routeId} (${protocol}): ${errorMessage}. First error: ${firstErrorTime}, duration: ${errorDurationSeconds}s`);
    // TODO: raise a DeviceAlert or other notification
} else if (eventType === 'inboundRecovered') {
    ec.logger.info(`Gateway inbound recovered on route ${routeId}: error duration was ${errorDurationSeconds}s since ${firstErrorTime}`);
    // TODO: clear DeviceAlert or other notification
} else {
    ec.logger.warn(`Unknown gateway notification eventType: ${eventType}`);
}
